CodeInjections.CodeInjection:
    float2 normalTexCoords : TEXCOORDn;
    float2 glossmapTexCoords : TEXCOORDn;
#if defined(DIRT_SECONDUV) || defined(ALPHA_MAP_SECONDUV)
    float2 customTexCoords2 : TEXCOORDn;
#endif

/*
    XY - scale the texture (horizontal/vertical)
    4x2 texture = 0.25/0.5
    ZW - offset uv incorporated into scale
    4x2 texture = (0,1,2,3)/(0,1) or (0,-1,-2,-3)/(0,-1)
*/
float4 mirrorScaleAndOffsetUV;
/*
    XY - invert size of the atlas (horizontal/vertical)
    4x2 texture = 0.25/0.5
    ZW - offset uv after XY applied (horizontal/vertical)
    4x2 texture = (0.0,0.25,0.5,0.75)/(0.0,0.5)
*/
float4 atlasInvSizeAndOffsetUV;
/* our additions: coatTint rgb multiplies the coat; coatShade x brightness y saturation w eye gloss; patternA rgb colour a strength */
float4 coatTint;
float4 coatShade;
float4 patternA;
#if defined( DIRT_ENABLED )
/*
    X - dirt amount 0..1
    YZ - dirtNmap uv scale
*/
    float3 dirt;
    float4 dirtColor; // color of the dirt
#endif
#if defined( SUBSURFACE_SCATTERING )
    float4 sssColor; // color of the fake subsurface scattering 
#endif

    float4 gGloss;
    float4 gCoatMask; // R coat, G eyeball, B hoof, A pattern A (1 0 0 0 without the mask)
#if defined( DIRT_ENABLED )
    float  gDirt;
#endif
#if defined( SUBSURFACE_SCATTERING )
    float gThickness;
    float gAlpha;
#endif

#if defined(DIRT_SECONDUV) || defined(ALPHA_MAP_SECONDUV) || defined(NORMAL_MAP_SECONDUV)
    // Pass second UVSet to the Pixel Shader
    Out.customTexCoords2 = convertDefaultTexCoords(In, object, In.texCoords1.xy);
#endif
    float2 newUV = getDefaultTexCoords(In, instance, object);
#if defined(NORMAL_MAP_SECONDUV)
    Out.normalTexCoords = Out.customTexCoords2;
#else
    // default behavior
    Out.normalTexCoords = newUV;
#endif
    Out.glossmapTexCoords = newUV;
    // mirror
    newUV = ((newUV-object.mirrorScaleAndOffsetUV.zw)*object.mirrorScaleAndOffsetUV.xy)+object.mirrorScaleAndOffsetUV.zw;
    // atlas
    newUV = newUV*object.atlasInvSizeAndOffsetUV.xy + object.atlasInvSizeAndOffsetUV.zw;
    Out.defaultTexCoords = newUV.xy;

globals.gGloss = float4(0.0,1.0,0.0,0.0);
#if defined( COAT_MASK )
    globals.gCoatMask = tex2DSample( coatMask, standardMaterialSampler, In.vs.glossmapTexCoords ).rgba;
#else
    globals.gCoatMask = float4(1.0,0.0,0.0,0.0);
#endif
#if defined( GLOSS_MAP )
    globals.gGloss = tex2DSample( glossMap, GLOSS_MAP_SAMPLER, In.vs.glossmapTexCoords).rgba;
#endif
#if defined( DIRT_ENABLED )
    #if defined( GLOSS_MAP )
        float texDirt  = 1 - globals.gGloss.b;
        #if defined(DIRT_SECONDUV)
            texDirt = 1 - tex2DSample( glossMap, GLOSS_MAP_SAMPLER, In.vs.customTexCoords2).b;
        #endif
        globals.gDirt  = saturate( (texDirt*1.05 - (object.dirt.x - 0.5)) * 2 );
    #else
        globals.gDirt = 1;
    #endif
#endif
#if defined( SUBSURFACE_SCATTERING )
    globals.gAlpha = 1.0;
    #if defined( GLOSS_MAP )
        globals.gThickness = globals.gGloss.a;
    #else
        globals.gThickness = 0.0;
    #endif
#endif

#if defined( DIRT_ENABLED )
    #if defined( NORMAL_MAP )
        float3 mNormal;
        #ifdef NORMAL_MAP_SIGNED_2CHANNEL
            // use BC5 signed format for the normal map
            mNormal.xy = tex2DSample(normalMap, NORMAL_MAP_SAMPLER, NORMAL_MAP_TEXCOORDS).xy;
            mNormal.z = sqrt(1.0 - dot(mNormal.xy, mNormal.xy));
        #else
            mNormal = tex2DSample(normalMap, NORMAL_MAP_SAMPLER, NORMAL_MAP_TEXCOORDS).xyz - 0.5;
        #endif
        float3 mDirtNmap = tex2DSample( dirtNmap, NORMAL_MAP_SAMPLER, float2( object.dirt.y, object.dirt.z ) * NORMAL_MAP_TEXCOORDS ).xyz - 0.5;
        return mNormal + float3(mDirtNmap.xy, 0.0) * (1 - globals.gDirt);
    #endif
#endif

    {   // our additions: the coat colour of this animal, then its pattern
        float3 shaded = diffuseColor * object.coatTint.rgb;
        float shadeLum = dot(shaded, float3(0.299, 0.587, 0.114));
        shaded = lerp(float3(shadeLum, shadeLum, shadeLum), shaded, object.coatShade.y) * object.coatShade.x;
        diffuseColor = lerp(diffuseColor, shaded, globals.gCoatMask.r);
        diffuseColor = lerp(diffuseColor, object.patternA.rgb, globals.gCoatMask.a * object.patternA.a);
    }
#if defined( DIRT_ENABLED )
    #if defined( SPECULAR ) && defined( GLOSS_MAP )
        diffuseColor = lerp( object.dirtColor.rgb, diffuseColor, globals.gDirt); // DirtColor lerp
    #endif
#endif


 #if defined( SUBSURFACE_SCATTERING )
    float fLTAmbient =      0.15;
    float fLTPower =        2.0;
    float fLTDistortion =   1.0;
    float fLTScale =        2.0;

    float fLightAttenuation = saturate(dot(normal, lightDir)) + saturate(dot(viewDir, -lightDir));

    float3 vLTLight = lightDir + normal * fLTDistortion;
    float fLTDot = pow(saturate(dot(viewDir, -vLTLight)), fLTPower) * fLTScale;
    float fLT = fLightAttenuation * (fLTDot + fLTAmbient) * globals.gThickness;
    float3 cLT = diffuseColor * lightColor * fLT * object.sssColor.rgb;
    #if defined(ALPHA_BLENDED)
        cLT *= globals.gAlpha;
    #endif
    #if defined( DIRT_ENABLED )
        cLT *= clamp(globals.gDirt,0.4,1.0);
    #endif
    lighting.xyz += cLT * lightAtten;
    #if defined( DEBUG_SHOW_PARALLAX )
        lighting.xyz = cLT * lightAtten;
    #endif
#endif

#if defined(ALPHA_TESTED) || defined(ALPHA_BLENDED)
    #if defined(ALBEDO_MAP)
        #if defined(ALPHA_MAP)
            alpha = tex2DSample(alphaMap, standardMaterialSampler, In.vs.glossmapTexCoords).x;
        #elif defined(ALPHA_MAP_SECONDUV)
            alpha = tex2DSample(alphaMap, standardMaterialSampler, In.vs.customTexCoords2).x;
        #else
            // Default Behaviour
            alpha = tex2DSample( baseMap, ALBEDO_MAP_SAMPLER, In.vs.glossmapTexCoords).a;
        #endif
    #endif
#endif
#if defined(ALPHA_BLENDED)
    reflectingLightingScale = alpha;
    #if defined( SUBSURFACE_SCATTERING )
        globals.gAlpha = alpha;
    #endif
#endif
